import pub.developers.forum.domain.repository.TagRepository;

import java.util.HashSet;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.*;

public class FaqManagerTest {

    @InjectMocks
    private FaqManager faqManager;

    @Mock
    private FaqRepository faqRepository;

    @Mock
    private TagRepository tagRepository;

    @BeforeEach
    public void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void saveFaq_createsNewFaq_whenFaqIdIsNull() {
        // Arrange
        FaqSaveFaqRequest request = new FaqSaveFaqRequest();
        request.setTagIds(new HashSet<>());

        when(tagRepository.queryInIds(anySet())).thenReturn(new HashSet<>());

        // Act
        Long result = faqManager.saveFaq(request);

        // Assert
        verify(faqRepository, times(1)).save(any(Faq.class));
        assertEquals(0L, result);
    }

    @Test
    public void saveFaq_updatesExistingFaq_whenFaqIdIsNotNull() {
        // Arrange
        FaqSaveFaqRequest request = new FaqSaveFaqRequest();
        request.setId(1L);
        request.setTagIds(new HashSet<>());

        when(faqRepository.get(anyLong())).thenReturn(new Faq());
        when(tagRepository.queryInIds(anySet())).thenReturn(new HashSet<>());

        // Act
        Long result = faqManager.saveFaq(request);

        // Assert
        verify(faqRepository, times(1)).update(any(Faq.class));
        assertEquals(1L, result);
    }

    @Test
    public void saveFaq_throwsException_whenFaqIdIsNotNullAndFaqDoesNotExist() {
        // Arrange
        FaqSaveFaqRequest request = new FaqSaveFaqRequest();
        request.setId(1L);
        request.setTagIds(new HashSet<>());

        when(faqRepository.get(anyLong())).thenReturn(null);

        // Act & Assert
        assertThrows(ErrorCodeEn.FAQ_NOT_EXIST, () -> faqManager.saveFaq(request));
    }
}

