import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import static org.mockito.Mockito.*;

class UserControllerTest {

    @Mock
    private UserApiService userApiService;

    @InjectMocks
    private UserController userController;

    private MockHttpServletRequest request;
    private MockHttpServletResponse response;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
        request = new MockHttpServletRequest();
        response = new MockHttpServletResponse();
    }

    @Test
    void logoutShouldCallUserServiceWithCorrectToken() {
        String token = "testToken";
        request.setCookies(new Cookie(WebConst.COOKIE_SID_NAME, token));

        userController.logout(response, request);

        verify(userApiService).logout(argThat(logoutRequest -> logoutRequest.getToken().equals(token)));
    }

    @Test
    void logoutShouldRemoveSidCookie() {
        String token = "testToken";
        request.setCookies(new Cookie(WebConst.COOKIE_SID_NAME, token));

        userController.logout(response, request);

        assertNull(response.getCookie(WebConst.COOKIE_SID_NAME));
    }

    @Test
    void logoutShouldRedirectToHomePage() {
        String token = "testToken";
        request.setCookies(new Cookie(WebConst.COOKIE_SID_NAME, token));

        String result = userController.logout(response, request);

        assertEquals(WebConst.REQUEST_REDIRECT_PREFIX + "/", result);
    }

    @Test
    void logoutShouldNotCallUserServiceWhenNoSidCookie() {
        userController.logout(response, request);

        verify(userApiService, never()).logout(any());
    }

    @Test
    void logoutShouldNotRemoveSidCookieWhenNoSidCookie() {
        userController.logout(response, request);

        assertNull(response.getCookie(WebConst.COOKIE_SID_NAME));
    }

    @Test
    void logoutShouldRedirectToHomePageWhenNoSidCookie() {
        String result = userController.logout(response, request);

        assertEquals(WebConst.REQUEST_REDIRECT_PREFIX + "/", result);
    }
}

