class CommentManagerTest {

    @Mock
    CommentRepository commentRepository;

    @Mock
    PostsRepository postsRepository;

    @Mock
    UserRepository userRepository;

    @InjectMocks
    CommentManager commentManager;

    @BeforeEach
    void setUp() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    void shouldCreateCommentWhenAllInputsAreValid() {
        CommentCreateRequest request = new CommentCreateRequest();
        request.setPostsId(1L);
        BasePosts posts = new BasePosts();
        User user = new User();
        when(postsRepository.get(request.getPostsId())).thenReturn(posts);
        when(userRepository.get(user.getId())).thenReturn(user);

        commentManager.create(request);

        verify(commentRepository, times(1)).save(any(Comment.class));
        verify(postsRepository, times(1)).increaseComments(anyLong(), any());
    }

    @Test
    void shouldNotCreateCommentWhenPostsNotExist() {
        CommentCreateRequest request = new CommentCreateRequest();
        request.setPostsId(1L);
        when(postsRepository.get(request.getPostsId())).thenReturn(null);

        commentManager.create(request);

        verify(commentRepository, times(0)).save(any(Comment.class));
    }

    @Test
    void shouldNotCreateCommentWhenReplyIdIsInvalid() {
        CommentCreateRequest request = new CommentCreateRequest();
        request.setPostsId(1L);
        request.setReplyId(1L);
        BasePosts posts = new BasePosts();
        when(postsRepository.get(request.getPostsId())).thenReturn(posts);
        when(commentRepository.get(request.getReplyId())).thenReturn(null);

        commentManager.create(request);

        verify(commentRepository, times(0)).save(any(Comment.class));
    }
}

