import pub.developers.forum.common.constant.Constant;
import pub.developers.forum.common.enums.CacheBizTypeEn;
import pub.developers.forum.domain.entity.User;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.*;

public class LoginUserAspectTest {

    @InjectMocks
    private LoginUserAspect loginUserAspect;

    @Mock
    private HttpServletRequest httpServletRequest;

    @Mock
    private CacheService cacheService;

    @Mock
    private ProceedingJoinPoint pjp;

    @BeforeEach
    public void setup() {
        MockitoAnnotations.openMocks(this);
    }

    @Test
    public void invokeProceedsWithoutToken() throws Throwable {
        when(httpServletRequest.getHeader(Constant.REQUEST_HEADER_TOKEN_KEY)).thenReturn(null);
        when(httpServletRequest.getAttribute(Constant.REQUEST_HEADER_TOKEN_KEY)).thenReturn(null);
        when(pjp.proceed()).thenReturn(new Object());

        Object result = loginUserAspect.invoke(pjp);

        verify(cacheService, never()).get(any(), any());
        assertEquals(new Object(), result);
    }

    @Test
    public void invokeProceedsWithTokenFromHeader() throws Throwable {
        String token = "token";
        User user = new User();
        when(httpServletRequest.getHeader(Constant.REQUEST_HEADER_TOKEN_KEY)).thenReturn(token);
        when(cacheService.get(CacheBizTypeEn.USER_LOGIN_TOKEN, token)).thenReturn(user);
        when(pjp.proceed()).thenReturn(new Object());

        Object result = loginUserAspect.invoke(pjp);

        verify(cacheService).get(CacheBizTypeEn.USER_LOGIN_TOKEN, token);
        assertEquals(new Object(), result);
    }

    @Test
    public void invokeProceedsWithTokenFromAttribute() throws Throwable {
        String token = "token";
        User user = new User();
        when(httpServletRequest.getHeader(Constant.REQUEST_HEADER_TOKEN_KEY)).thenReturn(null);
        when(httpServletRequest.getAttribute(Constant.REQUEST_HEADER_TOKEN_KEY)).thenReturn(token);
        when(cacheService.get(CacheBizTypeEn.USER_LOGIN_TOKEN, token)).thenReturn(user);
        when(pjp.proceed()).thenReturn(new Object());

        Object result = loginUserAspect.invoke(pjp);

        verify(cacheService).get(CacheBizTypeEn.USER_LOGIN_TOKEN, token);
        assertEquals(new Object(), result);
    }
}

